export async function startOrbital(paused){
 const T=await import('./vendor/three.module.js');
 const root=document.querySelector('#universe');root.replaceChildren();
 const renderer=new T.WebGLRenderer({alpha:false,antialias:true,powerPreference:'high-performance'});root.append(renderer.domElement);renderer.setPixelRatio(Math.min(devicePixelRatio,1.75));renderer.setSize(innerWidth,innerHeight);renderer.outputColorSpace=T.SRGBColorSpace;
 const scene=new T.Scene();scene.background=new T.Color(0x010207);const camera=new T.PerspectiveCamera(43,innerWidth/innerHeight,.01,1500);
 const loader=new T.TextureLoader();const textures=await Promise.all(['earth.jpg','earth-night.png','clouds.png'].map(n=>loader.loadAsync('./assets/'+n)));
 textures.forEach(t=>{t.anisotropy=renderer.capabilities.getMaxAnisotropy();});
 const globe=new T.Group();scene.add(globe);
 const material=new T.ShaderMaterial({uniforms:{day:{value:textures[0]},night:{value:textures[1]},sun:{value:new T.Vector3(-.6,.3,1).normalize()}},vertexShader:`varying vec2 vUv;varying vec3 n;varying vec3 viewDir;void main(){vUv=uv;n=normalize(mat3(modelMatrix)*normal);vec4 p=modelMatrix*vec4(position,1.);viewDir=normalize(cameraPosition-p.xyz);gl_Position=projectionMatrix*viewMatrix*p;}`,fragmentShader:`uniform sampler2D day;uniform sampler2D night;uniform vec3 sun;varying vec2 vUv;varying vec3 n;varying vec3 viewDir;void main(){vec3 normal=normalize(n);float light=dot(normal,sun);float daylight=smoothstep(-.12,.22,light);vec3 land=texture2D(day,vUv).rgb;vec3 cities=texture2D(night,vUv).rgb;float rim=pow(1.-max(dot(normal,normalize(viewDir)),0.),4.);vec3 color=land*(.025+max(light,0.)*1.12)*daylight+cities*.8*(1.-daylight)+vec3(.09,.28,.52)*rim*max(light+.35,0.);gl_FragColor=vec4(color,1.);}`});
 const earth=new T.Mesh(new T.SphereGeometry(10,160,96),material);earth.rotation.y=2;globe.add(earth);
 const clouds=new T.Mesh(new T.SphereGeometry(10.045,96,64),new T.MeshPhongMaterial({map:textures[2],transparent:true,opacity:.19,depthWrite:false,blending:T.AdditiveBlending}));clouds.rotation.y=2;globe.add(clouds);
 scene.add(new T.AmbientLight(0x718baf,.25));const light=new T.DirectionalLight(0xffffff,2.2);light.position.set(-30,15,50);scene.add(light);
 const atmosphere=new T.Mesh(new T.SphereGeometry(10.16,96,64),new T.ShaderMaterial({transparent:true,depthWrite:false,blending:T.AdditiveBlending,vertexShader:`varying vec3 n;varying vec3 v;void main(){vec4 p=modelViewMatrix*vec4(position,1.);n=normalize(normalMatrix*normal);v=normalize(-p.xyz);gl_Position=projectionMatrix*p;}`,fragmentShader:`varying vec3 n;varying vec3 v;void main(){float rim=pow(1.-abs(dot(normalize(n),normalize(v))),5.);gl_FragColor=vec4(.13,.38,.8,rim*.42);}`}));globe.add(atmosphere);
 let seed=71;const rand=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;};const positions=[];for(let i=0;i<2200;i++){const a=rand()*Math.PI*2,z=rand()*2-1,r=190+rand()*500;positions.push(Math.sqrt(1-z*z)*Math.cos(a)*r,z*r,Math.sqrt(1-z*z)*Math.sin(a)*r);}const geo=new T.BufferGeometry();geo.setAttribute('position',new T.Float32BufferAttribute(positions,3));scene.add(new T.Points(geo,new T.PointsMaterial({color:0xb8c7d8,size:.28,sizeAttenuation:true,transparent:true,opacity:.68})));
 const orbit=new T.Group();scene.add(orbit);const pts=[];for(let i=0;i<=240;i++){const a=i/240*Math.PI*2;pts.push(new T.Vector3(Math.cos(a)*15.3,0,Math.sin(a)*15.3));}orbit.add(new T.Line(new T.BufferGeometry().setFromPoints(pts),new T.LineBasicMaterial({color:0x647c99,transparent:true,opacity:.22})));orbit.rotation.z=.22;
 const sections=[...document.querySelectorAll('.chapter')],dots=[...document.querySelectorAll('#chapters a')];
 let active=-1,last=performance.now(),transition=null,orbitYaw=0,orbitPitch=0,drag=null;
 const views=[{a:.13,y:7,d:28,tx:-7,ty:2},{a:.55,y:10,d:25,tx:0,ty:5},{a:.85,y:4,d:26,tx:0,ty:5},{a:.24,y:16,d:40,tx:0,ty:0},{a:1.15,y:8,d:25,tx:0,ty:5},{a:.36,y:6,d:24,tx:0,ty:5},{a:-.42,y:11,d:27,tx:0,ty:5},{a:1.8,y:7,d:27,tx:0,ty:5},{a:2.4,y:11,d:31,tx:0,ty:5},{a:.9,y:16,d:32,tx:0,ty:5},{a:-.8,y:13,d:32,tx:0,ty:5},{a:-.2,y:3,d:23,tx:0,ty:5}];
 const look=new T.Vector3();const currentLook=new T.Vector3();
 function destination(index){const ids=['gateway','trust','mission','universe-map','ads','web','ai','social','data','results','flight','horizon'];const p=views[Math.max(0,ids.indexOf(sections[index].id))],mobile=innerWidth<700;return{pos:new T.Vector3(Math.sin(p.a)*p.d,p.y,Math.cos(p.a)*p.d),look:new T.Vector3(mobile?0:p.tx,p.ty+(mobile?1.5:0),0)};}
 function select(index,instant=false){if(index===active)return;active=index;orbitYaw=0;orbitPitch=0;const next=destination(index);transition={from:camera.position.clone(),to:next.pos,lookFrom:currentLook.clone(),lookTo:next.look,start:performance.now(),duration:instant||paused()?0:1350};document.querySelector('#location').textContent=sections[index].querySelector('.eyebrow').textContent;dots.forEach((d,i)=>{if(i===index)d.setAttribute('aria-current','step');else d.removeAttribute('aria-current');});document.querySelector('#progress').style.width=((index+1)/sections.length*100)+'%';}
 function detect(){let best=0,min=Infinity;sections.forEach((s,i)=>{const distance=Math.abs(s.getBoundingClientRect().top);if(distance<min){min=distance;best=i;}});select(best);}
 addEventListener('scroll',detect,{passive:true});addEventListener('resize',()=>{renderer.setSize(innerWidth,innerHeight);camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();const i=Math.max(0,active);active=-1;select(i,true);});
 document.addEventListener('click',event=>{const a=event.target.closest('a[href^="#"]');if(!a)return;const id=a.getAttribute('href').slice(1),index=sections.findIndex(s=>s.id===id);if(index<0)return;event.preventDefault();select(index);history.pushState(null,'','#'+id);sections[index].scrollIntoView({behavior:'instant',block:'start'});});
 addEventListener('popstate',()=>{const i=sections.findIndex(s=>'#'+s.id===location.hash);if(i>=0){sections[i].scrollIntoView({behavior:'instant'});select(i);}});
 // A held pointer on the background changes the viewing angle; content controls remain independent.
 renderer.domElement.addEventListener('pointerdown',e=>{if(paused())return;drag={x:e.clientX,y:e.clientY};renderer.domElement.setPointerCapture(e.pointerId);});renderer.domElement.addEventListener('pointermove',e=>{if(!drag)return;orbitYaw+=(e.clientX-drag.x)*.003;orbitPitch=Math.max(-.4,Math.min(.4,orbitPitch+(e.clientY-drag.y)*.002));drag={x:e.clientX,y:e.clientY};});renderer.domElement.addEventListener('pointerup',()=>drag=null);renderer.domElement.addEventListener('pointercancel',()=>drag=null);
 const initial=Math.max(0,sections.findIndex(s=>'#'+s.id===location.hash));camera.position.copy(destination(initial).pos);currentLook.copy(destination(initial).look);select(initial,true);sections[initial].scrollIntoView({behavior:'instant'});document.querySelector('#status').textContent='';
 function frame(now){requestAnimationFrame(frame);const dt=Math.min(.05,(now-last)/1000);last=now;if(document.hidden||document.body.classList.contains('solar-integrated'))return;if(transition){const t=transition.duration===0?1:Math.min(1,(now-transition.start)/transition.duration),e=t*t*(3-2*t);camera.position.lerpVectors(transition.from,transition.to,e);currentLook.lerpVectors(transition.lookFrom,transition.lookTo,e);if(t===1)transition=null;}else if(drag){const p=views[active];camera.position.set(Math.sin(p.a+orbitYaw)*p.d,p.y+orbitPitch*15,Math.cos(p.a+orbitYaw)*p.d);}if(!paused())clouds.rotation.y+=dt*.003;look.copy(currentLook);camera.lookAt(look);renderer.render(scene,camera);}requestAnimationFrame(frame);
 renderer.domElement.addEventListener('webglcontextlost',e=>{e.preventDefault();document.querySelector('#status').textContent='Cảnh 3D đã tạm ngắt. Nội dung vẫn dùng được; tải lại để mở cảnh.';});
}


